  if (!Object.keys(after).length) throw new HttpError(400, "Aucune modification"); const tot = poTotals(lines, fees.transportFee, fees.otherFees, Number(po.taxRatePct ?? 0)); data.total = tot.totalHt; const state: PoState = lines.every((l) => l.received >= l.qty) && lines.some((l) => l.received > 0) ? "received" : lines.some((l) => l.received > 0) ? "partial" : "validated"; data.status = state;
