  await gate(store, ctx); const r = await store.get("purchase_receipts", String(b.id ?? "")); if (!mine(ctx, r)) throw new HttpError(404, "Réception introuvable"); if (r.status === "validated") return { id: r.$id, status: "validated", duplicate: true }; if (r.status === "cancelled") throw new HttpError(409, "Réception annulée");
