  const rl = parse<RLine[]>(r.lines, []); const accepted = rl.filter((x) => x.accepted > 0); const receipts = parse<string[]>(po.receipts, []);
  let claim = ""; // rang réservé pour cette réception (libéré si la validation est refusée avant toute écriture)
