  if (typeof b.data !== "string" || !/^[A-Za-z0-9+/]+=*$/.test(b.data)) throw new HttpError(400, "Fichier invalide"); const bytes = new Uint8Array(Buffer.from(b.data, "base64")); if (bytes.length < 100) throw new HttpError(400, "Fichier invalide"); if (bytes.length > 1_800_000) throw new HttpError(413, "Document trop lourd (1,8 Mo maximum)"); const kind = MAGIC.find((m) => m.ok(bytes)); if (!kind) throw new HttpError(400, "Format non pris en charge (JPEG, PNG, WebP ou PDF)");
